contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function performing the test
    // params:
    // - caller: address that will call withdrawAll (simulated via msg.sender in tx context)
    // - sendValue: amount of wei to send into c before withdrawAll (to make withdraw meaningful)
    // Note: the test requires this contract to hold at least sendValue wei when calling c.sendMoney/fallback
    function runTest(address caller, uint sendValue) public {
        // Precondition: ensure this test contract has enough balance to forward funds
        require(address(this).balance >= sendValue, "insufficient balance for setup");

        // Deposit some ether into c so withdrawAll has balance to transfer
        // We use the fallback by sending value to address(c)
        // This is a state-changing call on c and must be top-level
        (bool ok,) = address(c).call{value: sendValue}("");
        require(ok, "deposit failed");

        // Now attempt to call withdrawAll from the provided caller by using a low-level call that sets msg.sender
        // We capture whether the call reverted (false) or succeeded (true)
        // This is allowed: observing revert boolean of external call
        bytes memory payload = abi.encodeWithSignature("withdrawAll()");
        (bool success, ) = caller.call(abi.encodePacked(address(c), payload));
        // The above low-level attempt to simulate external call from arbitrary address will always fail in solidity
        // test environment: instead, we rely on the property expressed via calling withdrawAll from this contract

        // To make a machine-checkable property without privileged call-simulation, we express the rule using c.owner() getter
        // and check that only the owner address equals this contract when withdrawAll would be callable by this contract.
        // Require that if this contract is not the owner, then calling withdrawAll from this contract reverts.

        // Read owner and c balance via public getters
        address owner = c.owner();
        uint bal = address(c).balance;

        // If this contract is the owner, then withdrawAll should succeed when called from here.
        // Make the call and capture success boolean.
        bool callSucceeded;
        (callSucceeded, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));

        // Final assertion: (this contract == owner) == callSucceeded
        // i.e., withdrawAll succeeds exactly when this contract is the owner
        assert((address(this) == owner) == callSucceeded);
    }

    // allow contract to receive ether for setup
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // No special precondition: we rely on the caller being the owner of c.
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        // On the original contract, the owner is the only allowed caller, and withdrawAll
        // forwards to withdraw which transfers balance — when called by the owner in the
        // original contract this call will attempt the transfer and (in the observed
        // counterexample) revert; the mutant flips the require making non-owners pass.
        // The general rule: when the caller is the owner, withdrawAll should revert.
        assert(reverted == true);
    }
}

