pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address deployer;
    function setUp() public { 
        c = new C();
        deployer = address(this); // test contract deployed C, so this is owner
    }

    // fuzzed params: a caller address and an amount to send through sendMoney
    function testFuzz_property(address caller, uint256 amount, bytes memory data) public {
        // keep amount in a sensible range so we can fund the caller and the contract
        amount = bound(amount, 0, 1 ether);

        // fund this test contract (the owner) and the fuzzed caller so they can send ETH
        vm.deal(deployer, 1 ether);
        vm.deal(caller, 1 ether);

        // Owner (this) sends some ETH into the contract by calling sendMoney targeting a benign receiver
        // We'll deploy a simple receiver that just accepts funds so the call succeeds
        Receiver recv = new Receiver();

        // Owner sends `amount` into the contract by calling sendMoney, which will forward it to recv
        vm.prank(deployer);
        c.sendMoney(address(recv), amount, data); // this transfers amount from contract to recv via call inside c

        // After sendMoney, the contract's balance may have changed; ensure contract has some balance by funding it directly
        // Fund the contract so withdrawAll has something to withdraw
        vm.deal(address(c), amount);

        // Now attempt to have the fuzzed caller call withdrawAll. Under the correct contract only the owner can withdrawAll,
        // so a non-owner call should NOT change owner-withdrawable funds. We'll observe whether withdrawAll succeeds by
        // catching reverts; but per rules we must assert only one assertTrue reading c's public surface.
        // Use try/catch to detect whether the call succeeded and then assert on address(c).balance.

        bool ok;
        // ensure caller has ETH to pay gas
        vm.prank(caller);
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // Property: If a non-owner (caller != deployer) invoked withdrawAll, the contract balance must remain the same (i.e., withdrawAll must not succeed).
        // For the reference contract, withdrawAll can only be called by owner, so for all inputs where caller != owner, withdrawAll cannot succeed and contract balance stays equal to amount.
        // For the mutant, there exist inputs where a non-owner can withdraw and reduce address(c).balance; the fuzzer will find such a case.

        if (caller != deployer) {
            // When caller is not the owner, the correct contract should prevent withdrawal; thus contract balance must remain equal to the funded amount.
            // We assert that either the call reverted (ok == false) OR, if it returned true, the balance is still amount (defensive), but to keep a single assertion reading c,
            // we assert that address(c).balance == amount, which holds for the reference for ALL such inputs and will be violated by the mutant for some input.
            assertTrue(address(c).balance == amount);
        } else {
            // If caller is the owner, withdrawAll may succeed and drain the contract. In that case the reference and mutant may behave differently; we avoid constraining this branch.
            // Just assert a trivial true by checking balance is <= amount (reads c) — but we must have exactly one assert in the function. To satisfy the single-assert rule,
            // we structure the test so that the above branch is the only place an assert is executed for the meaningful property. For owner==caller inputs we still execute the same assertion:
            assertTrue(address(c).balance == amount);
        }
    }
}

