pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner = address(0xABCD);

    function setUp() public { c = new C(); }

    // Fuzz the deposit amount so the fuzzer can find values > 0 that distinguish behavior
    function testFuzz_property(uint256 depositAmount) public {
        // keep domain wide but require a reasonable bound to avoid overflow in vm.deal
        depositAmount = bound(depositAmount, 0, 1 ether);

        // fund the owner so they can send depositAmount
        vm.deal(owner, depositAmount);

        // owner sends Ether to the contract triggering fallback (which increments depositsCount)
        vm.prank(owner);
        (bool sent,) = address(c).call{value: depositAmount}("");
        require(sent, "funding failed");

        // sanity: contract should hold the deposited funds
        // Now owner calls withdrawAll; since c.owner was set to deployer (this test contract), we must
        // call withdrawAll as the owner. The contract's owner is the address that deployed it (setUp uses new C()),
        // which is this test contract address. So we act as that address to call withdrawAll.

        // Ensure this test contract has a balance to receive funds (vm.deal for address(this))
        // not strictly necessary but keep wide
        vm.deal(address(this), 0);

        // Call withdrawAll from the owner (this contract) and observe final contract balance.
        // Use try/catch to capture any unexpected revert (not expected here).
        bool ok;
        try c.withdrawAll{gas: gasleft()}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for ANY depositAmount >= 0 the correct contract will transfer the
        // entire balance when withdrawAll is called, leaving address(c).balance == 0.
        // The mutant that calls withdraw(0) would leave the balance unchanged when depositAmount > 0.
        assertTrue(address(c).balance == 0);
    }
}

