pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: amount to deposit and an arbitrary payer address
    function testFuzz_property(uint256 depositAmount, address payer) public {
        // keep depositAmount in a reasonable non-negative ETH range and nonzero
        depositAmount = bound(depositAmount, 1, 1 ether);
        // avoid the zero address for payer to make vm.prank meaningful
        if (payer == address(0)) payer = address(1);

        // Deploy a helper that will send ETH to C via a low-level call triggering fallback
        Depositor depositor = new Depositor();

        // Fund the depositor and ensure it has ETH to send
        vm.deal(address(depositor), depositAmount);

        // Make the depositor perform a low-level call to C with value, which increments depositsCount via fallback
        depositor.sendTo{value: depositAmount}(address(c));

        // At this point, the contract should have a positive balance equal to depositAmount
        // Now have the owner (the deployer of c, i.e., address(this) in setUp) call withdrawAll
        // Ensure the caller is the owner
        vm.prank(address(this));
        c.withdrawAll();

        // The reference contract transfers the entire balance to the owner, leaving address(c).balance == 0
        // The mutant that calls withdraw(0) would leave the balance nonzero for some depositAmount inputs
        assertTrue(address(c).balance == 0);
    }
}

// Minimal helper that performs a low-level call to the target with value to trigger fallback()
contract Depositor {
    function sendTo(address target) public payable {
        // perform a low-level call forwarding all gas and value
        (bool,) = target.call{value: msg.value}("");
        // ignore return; we just want fallback to run on target
    }

    // Allow this contract to receive Ether
    receive() external payable {}
}

