import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz: amount to deposit and whether the recipient will revert (0 = normal, 1 = reverter)
    function testFuzz_property(uint256 depositAmount, uint8 attackerBehavior) public {
        // keep deposit amount within reasonable bounds (but allow zero too)
        depositAmount = bound(depositAmount, 0, 1 ether);
        // attackerBehavior should be 0 or 1
        attackerBehavior = attackerBehavior % 2;

        // deploy adversarial callee: either benign that accepts funds or reverter that reverts on receive
        address payable recipient;
