        // Ensure caller is an EOA by forbidding the address of this test contract and the C contract.
        // (Fuzzer could still pick addresses that have code in the local fork; keep domain wide.)
        vm.assume(caller != address(this));
        vm.assume(caller != address(c));

        // Fund the caller so it can send deposit to c if needed
        vm.deal(caller, deposit + 1 wei);

        // If deposit > 0, have caller send Ether to c via plain transfer (triggers fallback incrementing depositsCount)
        if (deposit > 0) {
            vm.prank(caller);
            (bool sent, ) = address(c).call{value: deposit}("");
            // plain transfer to C should succeed in normal EVM environment; if it fails for some unusual caller, skip that input
            if (!sent) return;
        }

        // Record balance before the withdraw attempt
        uint256 before = address(c).balance;

        // Try to have the arbitrary EOA caller issue withdraw(withdrawAmount)
        bool ok;
        vm.prank(caller);
        try c.withdraw(withdrawAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        // After an EOA (not address(this)) calls withdraw, the reference contract enforces that only owner EOA can cause transfers out.
        // Thus for all inputs where caller != owner, the call must not succeed in making the contract lose ETH.
